func (s pageIndexHandlers) GET(w http.ResponseWriter, r *http.Request) {
	sess, _, ok := s.ReadSession(w, r)
	if !ok {
		return
	}

	if r.URL.Path != "/" {
		s.render404(w, r)
		return
	}

	var query datapages.Query[dpapp.SearchParams]
	query.Values.Term = httpread.QueryValue(r.URL.RawQuery, "q")
	pageCache := newPageCache(s.Server, r, nil)

	p := dpapp.PageIndex{
		App: s.app,
		Base: dpapp.Base{
			App: s.app,
		},
	}
	defer s.recoverPanic(w, r, nil, "PageIndex.GET")
	body, err := p.GET(r, sess, pageCache, query)
	if err != nil {
		s.httpErrIntern(w, r, nil, "handling PageIndex.GET", err)
		return
	}
	genericHead := s.app.Head(r)

	bodyAttrs := func(w http.ResponseWriter) {
		httpserve.WriteReloadOnVisibility(w)

		_, _ = io.WriteString(w, ` data-signals:q="'`)
		htmlattr.WriteSignalString(w, query.Values.Term)
		_, _ = io.WriteString(w, `'"`)
	}

	bodySuffix := func(w http.ResponseWriter) {

		_, _ = io.WriteString(w, ` data-effect="const params = new URLSearchParams(location.search);
			if ($q) params.set('q', $q); else params.delete('q');
			const query = params.toString();
			window.history.replaceState(null, '', query ? '/?' + query : '/');
		"`)
	}

	if err := s.writeHTML(
		w, r, sess, genericHead, nil, pageCache.bakeInto(body), bodyAttrs, bodySuffix,
	); err != nil {
		s.LogErr("rendering PageIndex", err)
		return
	}
}

