func (s pageLoginHandlers) POSTSubmit(
	w http.ResponseWriter, r *http.Request,
) {
	if !s.CheckDatastarRequest(w, r) {
		return
	}
	sess, _, ok := s.ReadSession(w, r)
	if !ok {
		return
	}
	httpserve.LimitRequestBody(w, r, s.BodySizeLimit())
	var signals datapages.Signals[struct {
		EmailOrUsername string `json:"emailorusername"`
		Password        string `json:"password"`
		Next            string `json:"next"`
	}]
	if err := datastar.ReadSignals(r, &signals.Values); err != nil {
		s.HTTPErrBad(w, "reading signals", err)
		return
	}
	defer s.recoverPanic(w, r, nil, "PageLogin.Submit")
	pageCache := newPageCache(s.Server, r, nil)
	p := dpapp.PageLogin{
		App: s.app,
	}
	body, redirect, newSession, err := p.POSTSubmit(r, sess, pageCache, signals)
	if err != nil {
		s.httpErrIntern(w, r, nil, "handling action PageLogin.Submit", err)
		return
	}
	if j := newSession; j.UserID != "" {
		created, err := s.CreateSession(w, r, newSession)
		if err != nil {
			s.httpErrIntern(w, r, nil, "creating session", err)
			return
		}
		sess = created
	}
	if httpRedirectOffline(w, r, redirect, pageCache) {
		return
	}
	genericHead := s.app.Head(r)
	if err := s.writeHTML(
		w, r, sess, genericHead, nil, body, nil, nil,
	); err != nil {
		s.LogErr("rendering response of PageLogin.POSTSubmit", err)
		return
	}
}

